#pragma once

// WGS84 geographic -> UTM (Universal Transverse Mercator).
//
// Implementation: Krüger series to 6th order in the third flattening n
// (Karney 2011, "Transverse Mercator with an accuracy of a few nanometres").
// Accurate to well below 1 mm inside a zone. Verified against pyproj in
// test/test_utm using vectors generated by tools/gen_utm_vectors.py.

#include <cstdint>

namespace geo {

struct Utm {
  uint8_t zone;      // 1..60
  char hemisphere;   // 'N' or 'S'
  double easting;    // m
  double northing;   // m
};

// Standard UTM zone for a position, including the Norway (32V) and
// Svalbard (31X..37X) exceptions. Returns 0 if latitude is outside [-80, 84].
uint8_t utmZone(double latDeg, double lonDeg);

// Converts using the standard zone. Returns false outside UTM coverage.
bool latLonToUtm(double latDeg, double lonDeg, Utm& out);

// Converts into a forced zone (e.g. to keep a whole survey in one zone).
bool latLonToUtmInZone(double latDeg, double lonDeg, uint8_t zone, Utm& out);

}  // namespace geo
